  "claim": {
    "component_id": "C024",
    "value": "The elimination procedure stops when the confidently classified endpoint revisions are adjacent.",
    "scope": "Successful stopping condition for the good/bad endpoint procedure.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
